CREATE TABLE "developer_oauth_apps" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"owner_business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"created_by_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"name" text NOT NULL,"client_id" text NOT NULL UNIQUE,"client_secret_hash" text NOT NULL,"redirect_uris" json NOT NULL DEFAULT '[]'::json,"scopes" json NOT NULL DEFAULT '[]'::json,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "developer_oauth_apps_status_check" CHECK("status" IN ('active','revoked')));
CREATE INDEX "developer_oauth_apps_owner_created_idx" ON "developer_oauth_apps"("owner_business_id","created_at");
CREATE TABLE "developer_oauth_installations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"app_id" uuid NOT NULL REFERENCES "developer_oauth_apps"("id") ON DELETE cascade,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"installed_by_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"scopes" json NOT NULL DEFAULT '[]'::json,"status" text NOT NULL DEFAULT 'active',"installed_at" timestamp NOT NULL DEFAULT now(),"revoked_at" timestamp,"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "developer_oauth_installations_status_check" CHECK("status" IN ('active','revoked')),CONSTRAINT "developer_oauth_installations_app_business_unique" UNIQUE("app_id","business_id"));
CREATE TABLE "developer_oauth_authorization_codes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"installation_id" uuid NOT NULL REFERENCES "developer_oauth_installations"("id") ON DELETE cascade,"code_hash" text NOT NULL UNIQUE,"redirect_uri" text NOT NULL,"scopes" json NOT NULL DEFAULT '[]'::json,"expires_at" timestamp NOT NULL,"consumed_at" timestamp,"created_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX "developer_oauth_authorization_codes_expires_idx" ON "developer_oauth_authorization_codes"("expires_at");
CREATE TABLE "developer_oauth_access_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"installation_id" uuid NOT NULL REFERENCES "developer_oauth_installations"("id") ON DELETE cascade,"token_prefix" text NOT NULL,"token_hash" text NOT NULL UNIQUE,"scopes" json NOT NULL DEFAULT '[]'::json,"expires_at" timestamp NOT NULL,"last_used_at" timestamp,"revoked_at" timestamp,"created_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX "developer_oauth_access_tokens_installation_created_idx" ON "developer_oauth_access_tokens"("installation_id","created_at");
CREATE TABLE "developer_oauth_refresh_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"installation_id" uuid NOT NULL REFERENCES "developer_oauth_installations"("id") ON DELETE cascade,"family_id" uuid NOT NULL,"token_hash" text NOT NULL UNIQUE,"scopes" json NOT NULL DEFAULT '[]'::json,"expires_at" timestamp NOT NULL,"rotated_at" timestamp,"revoked_at" timestamp,"created_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX "developer_oauth_refresh_tokens_family_idx" ON "developer_oauth_refresh_tokens"("family_id");
CREATE INDEX "developer_oauth_refresh_tokens_installation_idx" ON "developer_oauth_refresh_tokens"("installation_id");
CREATE TABLE "developer_oauth_rate_windows" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"access_token_id" uuid NOT NULL REFERENCES "developer_oauth_access_tokens"("id") ON DELETE cascade,"window_started_at" timestamp NOT NULL,"request_count" integer NOT NULL DEFAULT 0,"expires_at" timestamp NOT NULL,CONSTRAINT "developer_oauth_rate_windows_count_check" CHECK("request_count" >= 0),CONSTRAINT "developer_oauth_rate_windows_token_window_unique" UNIQUE("access_token_id","window_started_at"));
CREATE INDEX "developer_oauth_rate_windows_expires_idx" ON "developer_oauth_rate_windows"("expires_at");
